mapper.insert:

/* systemsvc.MenuMapper.insertMenu(메뉴 등록) */
INSERT INTO menus (
    parent_menu_id
    ,menu_cd
    ,menu_nm
    ,menu_type
    ,path
    ,component
    ,icon
    ,depth
    ,sort_seq
    ,visible_yn
    ,use_yn
    ,remark
    ,created_by
    ,created_at
    ,updated_by
    ,updated_at
)
VALUES (
    #{data.parentMenuId}
    ,#{data.menuCd}
    ,#{data.menuNm}
    ,COALESCE(#{data.menuType}, 'MENU')
    ,#{data.path}
    ,#{data.component}
    ,#{data.icon}
    ,COALESCE(#{data.depth}, 1)
    ,COALESCE(#{data.sortSeq}, 0)
    ,COALESCE(#{data.visibleYn}, 'Y')
    ,COALESCE(#{data.useYn}, 'Y')
    ,#{data.remark}
    ,#{data.createdBy}
    ,current_timestamp
    ,#{data.createdBy}
    ,current_timestamp
)

mapper.update:

/* systemsvc.MenuMapper.updateMenu(메뉴 수정) */
UPDATE menus
SET parent_menu_id = #{data.parentMenuId}
    ,menu_nm = #{data.menuNm}
    ,menu_type = COALESCE(#{data.menuType}, menu_type)
    ,path = #{data.path}
    ,component = #{data.component}
    ,icon = #{data.icon}
    ,depth = COALESCE(#{data.depth}, depth)
    ,sort_seq = COALESCE(#{data.sortSeq}, sort_seq)
    ,visible_yn = COALESCE(#{data.visibleYn}, visible_yn)
    ,use_yn = COALESCE(#{data.useYn}, use_yn)
    ,remark = #{data.remark}
    ,updated_by = #{data.createdBy}
    ,updated_at = current_timestamp
WHERE menu_id = #{data.menuId}

mapper.delete:

