/* systemsvc.MenuMapper.insertRoleMenu(역할별 메뉴 권한 등록) */
INSERT INTO role_menus (
    role_id
    ,menu_id
    ,created_by
    ,created_at
    ,updated_by
    ,updated_at
)
VALUES (
    #{roleId}
    ,#{menuId}
    ,#{createdBy}
    ,current_timestamp
    ,#{createdBy}
    ,current_timestamp
)

